  for my $arg ($ch, "a".$ch."b.com") {
    open my $fh, "-|", $exe, $arg or die $!;
    my @out = map { chomp; $_ } <$fh>;
    close $fh;
    my @shown = map { sprintf "\\x{%02X}", ord } split //, $arg;
    printf "U+%04X %-35s input=%s out=[%s]\n", $cp, $name, join("", @shown), join(",", @out);
  }
}
